py -V:3.12 -I -B -c "import json,pathlib; r=pathlib.Path('.'); c=json.loads((r/'scratch/t14/out/census.json').read_text(encoding='utf-8')); s=json.loads((r/'reports/stage2_table_identity.json').read_text(encoding='utf-8')); print('T14_CLASSES'); [print(x.get('table_type'),x.get('status'),x.get('handler_off'),x.get('primary_class'),x.get('entity_tag'),','.join(sorted({v.get('class','') for v in x.get('vtables',[])}))) for x in c['tables']]; print('STAGE2_ROWS'); [print(x.get('table_type'),x.get('status'),x.get('entity'),x.get('role')) for x in s.get('rows',[])]; print('T24_TARGETS');
for p in sorted((r/'scratch/t24/out').glob('subtables.part00*.json')):
 d=json.loads(p.read_text(encoding='utf-8'));
 for x in d.get('nested_fields',[]):
  if x.get('idx') in list(range(370,399))+list(range(400,419)): print(p.name,json.dumps(x,ensure_ascii=False))"

py -V:3.12 -I -B -c "import runpy,pathlib,hashlib; d=runpy.run_path('scripts/fm24_dump.py'); c=d['_reader'](); dbdir=pathlib.Path('scratch/data'); magic=d['MAGIC'];
for a in ('client','server'):
 fn=f'{a}_db.dat'; p=dbdir/fn; es=c['list_tables'](p,fn); e=c['_resolve_table'](3,es,fn); rawdb=p.read_bytes(); base=e['offset']; hits=[i for i in range(base,min(base+128,len(rawdb))) if rawdb[i:i+4]==magic]; print(a,'offset',base,'frame_hits',hits);
 for h in hits:
  try:
   out=c['_stream_decompress'](rawdb[h:],256*1024*1024); print(' ',h-base,len(out),hashlib.sha256(out).hexdigest(),out[:20].hex())
  except Exception as x: print(' ',h-base,type(x).__name__,str(x)[:160])"

